import{_ as r,l as i,o as e,c as n,v as o,p as l,x as t,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"调试信息 DWARF","description":"","frontmatter":{"title":"调试信息 DWARF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dwarf-debug-info.md","filePath":"cs/dwarf-debug-info.md","lastUpdated":1789023840000}'),D={name:"cs/dwarf-debug-info.md"};function h(A,a,_,u,f,m){const d=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="调试信息-dwarf" tabindex="-1">调试信息 DWARF <a class="header-anchor" href="#调试信息-dwarf" aria-label="Permalink to &quot;调试信息 DWARF&quot;">​</a></h1><div class="epigraph"><p>优化把值放进寄存器并删语句，源级调试靠 DWARF：行号表、位置列表、类型 DIE。信息必须随变换更新，否则断点落空。</p><footer>—— 据 DWARF 标准；Tichy 等调试优化代码的讨论；主干编译器通行证整理</footer></div><p>上一课<a href="/cs/stack-unwinding">unwind</a>用了 DWARF CFI。缺口是<strong>源级调试</strong>：哪一行、变量现在哪、类型布局。优化编译器要么保守少优化，要么发复杂 location list。本课钉 DIE 与行表，不写 GDB 协议。符号 mangling 下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DCE 删赋值，变量「当前无位置」。内联：同一源行多个实例，需 <code>DW_TAG_inlined_subroutine</code>。缺口是<strong>元数据与 IR 同步</strong>，不是 FDE 查找。</p><p>行号：<code>is_stmt</code> 标记语句边界，方便断点。调度打乱序，行表可非单调。</p><h3 id="dwarf-不是「关掉优化」" tabindex="-1">DWARF 不是「关掉优化」 <a class="header-anchor" href="#dwarf-不是「关掉优化」" aria-label="Permalink to &quot;DWARF 不是「关掉优化」&quot;">​</a></h3><p><code>-O2 -g</code> 合法：信息尽量描述优化后的机器。质量参差。不要假设 <code>x</code> 总在栈槽。</p><p><span class="marginnote">DWARF 5。GCC/LLVM 的 DI 元数据。本课不把 CodeView 写完，只点名 MSVC 另一格式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前端发 <code>dbg.value</code>/<code>dbg.declare</code>。优化传递：复制、删除时更新。后端：寄存器分配后写成 location list（按 PC 区间）。类型：从语言类型降到 DIE。</p>',11)),(e(),l(p,null,{default:t(()=>[c(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E4%BD%8D%E7%BD%AE%22%5D%20--%3E%20DI%5B%22IR%20%E8%B0%83%E8%AF%95%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A%20%20DI%20--%3E%20OPT%5B%22%E9%9A%8F%E4%BC%98%E5%8C%96%E6%9B%B4%E6%96%B0%22%5D%0A%20%20OPT%20--%3E%20DW%5B%22DWARF%20%E8%8A%82%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与 SROA：字段拆开要多个 location。与合并：两变量同寄存器，调试器按 PC 区分。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>体积：<code>-g</code> 显著增大。分离：<code>.dwo</code>/dsym。strip 后只留 unwind 或全无。不要把密钥写进调试字符串。</p><p>ASan 改变布局，调试信息要跟。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写表达式求值器全部 DWARF ops。后课默认：优化代码用位置列表。下一课符号与 mangling：链接与调试都看见的名字。</p><p>也不把 DWARF 当核心转储格式的全部（ELF note 另有）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DWARF：行号、类型、变量位置，随优化更新。</li><li>内联与 SSA 析构是主要难点。</li><li>CFI 是 DWARF 的一部分，服务展开。</li><li>出处：DWARF 标准；对照 Appel/龙书调试支持。</li></ul>',9))])}const g=r(D,[["render",h]]);export{b as __pageData,g as default};
